import numpy as np
from causallearn.graph.GeneralGraph import GeneralGraph
from causallearn.graph.GraphNode import GraphNode

# =====================================================================
# EDITABLE: implement run_causal_discovery below
# =====================================================================
def run_causal_discovery(X: np.ndarray) -> GeneralGraph:
    """
    GES-warmstarted Hill Climbing (GES-HC):

    A hybrid causal discovery algorithm that combines:
    1. GES (Greedy Equivalence Search) for global structure in CPDAG space
    2. HC (Hill Climbing) for local refinement in DAG space

    The key insight: GES explores CPDAG space with insert/delete operators,
    while HC explores DAG space with add/delete/reverse operators. These
    different search spaces have different local optima. Starting HC from
    a DAG consistent with GES's solution combines global exploration with
    local exploitation, finding better solutions than either alone.
    """
    from causallearn.search.ScoreBased.GES import ges
    from causallearn.score.LocalScoreFunctionClass import LocalScoreClass
    from causallearn.score.LocalScoreFunction import local_score_BDeu
    from causallearn.utils.DAG2CPDAG import dag2cpdag
    from causallearn.graph.Endpoint import Endpoint

    N = X.shape[1]
    nodes = [GraphNode(f"X{i+1}") for i in range(N)]

    # Phase 1: GES for initial structure (global search in CPDAG space)
    ges_result = ges(
        X, score_func="local_score_BDeu",
        parameters={"sample_prior": 1.0, "structure_prior": 1.0},
    )
    ges_G = ges_result["G"]

    # Phase 2: Extract DAG from GES CPDAG via consistent extension
    dir_adj = np.zeros((N, N), dtype=int)
    undir_pairs = set()

    for i in range(N):
        for j in range(i + 1, N):
            edge = ges_G.get_edge(ges_G.nodes[i], ges_G.nodes[j])
            if edge is None:
                continue
            ep1 = edge.get_endpoint1()
            ep2 = edge.get_endpoint2()
            if ep1 == Endpoint.TAIL and ep2 == Endpoint.ARROW:
                dir_adj[i, j] = 1
            elif ep1 == Endpoint.ARROW and ep2 == Endpoint.TAIL:
                dir_adj[j, i] = 1
            else:
                # Undirected or circle endpoints
                undir_pairs.add((i, j))

    # Topological ordering on compelled edges for acyclic DAG extension
    in_deg = np.sum(dir_adj, axis=0).astype(int)
    temp_in = in_deg.copy()
    queue = sorted([i for i in range(N) if temp_in[i] == 0])
    order = []
    while queue:
        node = queue.pop(0)
        order.append(node)
        for j in range(N):
            if dir_adj[node, j] == 1:
                temp_in[j] -= 1
                if temp_in[j] == 0:
                    queue.append(j)
                    queue.sort()
    # Add remaining nodes (shouldn't happen with valid CPDAG)
    order_set = set(order)
    for i in range(N):
        if i not in order_set:
            order.append(i)
    pos = {nd: idx for idx, nd in enumerate(order)}

    # Build initial DAG: compelled edges + undirected edges by topo order
    adj = dir_adj.copy()
    for (i, j) in undir_pairs:
        if adj[i, j] == 0 and adj[j, i] == 0:
            if pos[i] < pos[j]:
                adj[i, j] = 1
            else:
                adj[j, i] = 1

    # Phase 3: Hill climbing refinement in DAG space
    score_func = LocalScoreClass(
        data=X, local_score_fun=local_score_BDeu, parameters=None
    )

    local_scores = np.zeros(N)
    for j in range(N):
        local_scores[j] = score_func.score(
            j, sorted(np.where(adj[:, j] == 1)[0].tolist())
        )

    def _has_path(src, tgt):
        """DFS check: directed path from src to tgt?"""
        visited = set()
        stack = [src]
        while stack:
            nd = stack.pop()
            if nd == tgt:
                return True
            if nd in visited:
                continue
            visited.add(nd)
            for c in np.where(adj[nd] == 1)[0]:
                if int(c) not in visited:
                    stack.append(int(c))
        return False

    improved = True
    while improved:
        improved = False
        best_delta = 0.0
        best_op = None

        for i in range(N):
            for j in range(N):
                if i == j:
                    continue

                if adj[i, j] == 0 and adj[j, i] == 0:
                    # --- Try ADD i -> j ---
                    if not _has_path(j, i):
                        pj_new = sorted(
                            np.where(adj[:, j] == 1)[0].tolist() + [i]
                        )
                        new_sj = score_func.score(j, pj_new)
                        delta = new_sj - local_scores[j]
                        if delta < best_delta - 1e-6:
                            best_delta = delta
                            best_op = ("add", i, j)

                elif adj[i, j] == 1:
                    # --- Try DELETE i -> j ---
                    pj_new = [
                        p for p in np.where(adj[:, j] == 1)[0] if p != i
                    ]
                    new_sj = score_func.score(j, sorted(pj_new))
                    delta = new_sj - local_scores[j]
                    if delta < best_delta - 1e-6:
                        best_delta = delta
                        best_op = ("delete", i, j)

                    # --- Try REVERSE i -> j to j -> i ---
                    adj[i, j] = 0
                    if not _has_path(i, j):
                        pj_del = sorted(
                            np.where(adj[:, j] == 1)[0].tolist()
                        )
                        new_sj = score_func.score(j, pj_del)
                        pi_new = sorted(
                            np.where(adj[:, i] == 1)[0].tolist() + [j]
                        )
                        new_si = score_func.score(i, pi_new)
                        delta = (
                            (new_sj - local_scores[j])
                            + (new_si - local_scores[i])
                        )
                        if delta < best_delta - 1e-6:
                            best_delta = delta
                            best_op = ("reverse", i, j)
                    adj[i, j] = 1

        if best_op is not None:
            op_type, i, j = best_op
            if op_type == "add":
                adj[i, j] = 1
            elif op_type == "delete":
                adj[i, j] = 0
            elif op_type == "reverse":
                adj[i, j] = 0
                adj[j, i] = 1
            local_scores[j] = score_func.score(
                j, sorted(np.where(adj[:, j] == 1)[0].tolist())
            )
            if op_type == "reverse":
                local_scores[i] = score_func.score(
                    i, sorted(np.where(adj[:, i] == 1)[0].tolist())
                )
            improved = True

    # Phase 4: Convert final DAG to CPDAG
    G = GeneralGraph(nodes)
    for i in range(N):
        for j in range(N):
            if adj[i, j] == 1:
                G.add_directed_edge(nodes[i], nodes[j])
    G = dag2cpdag(G)
    return G
# =====================================================================

import numpy as np
from causallearn.graph.GeneralGraph import GeneralGraph
from causallearn.graph.GraphNode import GraphNode

# =====================================================================
# EDITABLE: implement run_causal_discovery below
# =====================================================================
def run_causal_discovery(X: np.ndarray) -> GeneralGraph:
    """
    Score-Guided Multi-Strategy Causal Discovery (SG-MSD).

    Novel algorithmic contribution: a multi-space optimization framework that
    combines score-based (GES), permutation-based (BOSS, GRaSP) search
    strategies with a correct DAG-space hill climbing refinement.

    Key insights:
    1. Different algorithms explore different neighborhoods of the model space
       and may find different local optima of the same BDeu objective.
    2. Score-based model selection across strategies effectively performs
       multi-start optimization without additional structural assumptions.
    3. A final DAG-space hill climbing pass (with correct gradient direction)
       can escape local optima that CPDAG-space or permutation-space search
       gets stuck in, providing fine-grained refinement.
    """
    from causallearn.search.ScoreBased.GES import ges
    from causallearn.search.PermutationBased.BOSS import boss
    from causallearn.score.LocalScoreFunctionClass import LocalScoreClass
    from causallearn.score.LocalScoreFunction import local_score_BDeu
    from causallearn.utils.DAG2CPDAG import dag2cpdag
    from causallearn.graph.Endpoint import Endpoint

    N = X.shape[1]
    nodes = [GraphNode(f"X{i+1}") for i in range(N)]
    score_func = LocalScoreClass(
        data=X, local_score_fun=local_score_BDeu, parameters=None
    )

    def graph_to_dag(G):
        """Extract a consistent DAG extension from a CPDAG GeneralGraph."""
        dag = np.zeros((N, N), dtype=int)
        undir = []
        for e in G.get_graph_edges():
            i = G.get_node_index(e.get_node1())
            j = G.get_node_index(e.get_node2())
            e1, e2 = e.get_endpoint1(), e.get_endpoint2()
            if e1 == Endpoint.TAIL and e2 == Endpoint.ARROW:
                dag[i, j] = 1
            elif e1 == Endpoint.ARROW and e2 == Endpoint.TAIL:
                dag[j, i] = 1
            else:
                undir.append((min(i, j), max(i, j)))
        # Topological sort on directed edges for consistent extension
        ind = dag.sum(axis=0)
        q = [int(x) for x in np.where(ind == 0)[0]]
        topo, tmp = [], ind.copy()
        while q:
            n = q.pop(0)
            topo.append(n)
            for jj in range(N):
                if dag[n, jj] == 1:
                    tmp[jj] -= 1
                    if tmp[jj] == 0:
                        q.append(jj)
        for i in range(N):
            if i not in topo:
                topo.append(i)
        pos = {n: k for k, n in enumerate(topo)}
        for (i, j) in undir:
            if pos[i] < pos[j]:
                dag[i, j] = 1
            else:
                dag[j, i] = 1
        return dag

    def score_dag(dag):
        """Compute total BDeu score of a DAG."""
        return sum(
            score_func.score(j, sorted(np.where(dag[:, j] == 1)[0].tolist()))
            for j in range(N)
        )

    def has_path(dag, s, t):
        """DFS check for directed path from s to t."""
        vis, stk = set(), [s]
        while stk:
            n = stk.pop()
            if n == t:
                return True
            if n in vis:
                continue
            vis.add(n)
            stk.extend(
                int(c) for c in np.where(dag[n] == 1)[0] if int(c) not in vis
            )
        return False

    def hc_refine(dag, max_iters=50):
        """
        Hill climbing in DAG space — maximizes BDeu score.

        Unlike the HC baseline (which uses delta < 0, effectively performing
        hill descent), this correctly seeks positive score improvements.
        """
        ls = np.array([
            score_func.score(j, sorted(np.where(dag[:, j] == 1)[0].tolist()))
            for j in range(N)
        ])
        for _ in range(max_iters):
            bd, bo = 0.0, None
            for i in range(N):
                for j in range(N):
                    if i == j:
                        continue
                    if dag[i, j] == 0 and dag[j, i] == 0:
                        # Try ADD i -> j
                        if not has_path(dag, j, i):
                            pj = sorted(
                                np.where(dag[:, j] == 1)[0].tolist() + [i]
                            )
                            d = score_func.score(j, pj) - ls[j]
                            if d > bd + 1e-6:
                                bd, bo = d, ("a", i, j)
                    elif dag[i, j] == 1:
                        # Try DELETE i -> j
                        pj = sorted(
                            [int(p) for p in np.where(dag[:, j] == 1)[0] if p != i]
                        )
                        d = score_func.score(j, pj) - ls[j]
                        if d > bd + 1e-6:
                            bd, bo = d, ("d", i, j)
                        # Try REVERSE i -> j to j -> i
                        dag[i, j] = 0
                        if not has_path(dag, i, j):
                            pd = sorted(np.where(dag[:, j] == 1)[0].tolist())
                            pn = sorted(
                                np.where(dag[:, i] == 1)[0].tolist() + [j]
                            )
                            d = (
                                score_func.score(j, pd) - ls[j]
                                + score_func.score(i, pn) - ls[i]
                            )
                            if d > bd + 1e-6:
                                bd, bo = d, ("r", i, j)
                        dag[i, j] = 1
            if bo is None:
                break
            op, i, j = bo
            if op == "a":
                dag[i, j] = 1
            elif op == "d":
                dag[i, j] = 0
            else:
                dag[i, j] = 0
                dag[j, i] = 1
            ls[j] = score_func.score(
                j, sorted(np.where(dag[:, j] == 1)[0].tolist())
            )
            if op == "r":
                ls[i] = score_func.score(
                    i, sorted(np.where(dag[:, i] == 1)[0].tolist())
                )
        return dag

    def to_cpdag(dag):
        """Convert DAG adjacency to CPDAG GeneralGraph."""
        G = GeneralGraph(nodes)
        for i in range(N):
            for j in range(N):
                if dag[i, j] == 1:
                    G.add_directed_edge(nodes[i], nodes[j])
        return dag2cpdag(G)

    # ---- Phase 1: Collect candidate CPDAGs from diverse strategies ----
    cands = []

    # Strategy 1: GES (score-based, CPDAG-space search)
    try:
        r = ges(
            X, score_func="local_score_BDeu",
            parameters={"sample_prior": 1.0, "structure_prior": 1.0},
        )
        cands.append(r["G"])
    except Exception:
        pass

    # Strategy 2: BOSS (permutation-based, best-order search)
    try:
        G_boss = boss(
            X, score_func="local_score_BDeu",
            parameters={"sample_prior": 1.0, "structure_prior": 1.0},
        )
        cands.append(G_boss)
    except Exception:
        pass

    # Strategy 3: GRaSP (permutation-based, greedy relaxation)
    try:
        from causallearn.search.PermutationBased.GRaSP import grasp
        G_grasp = grasp(
            X, score_func="local_score_BDeu", depth=3,
            parameters={"sample_prior": 1.0, "structure_prior": 1.0},
        )
        cands.append(G_grasp)
    except Exception:
        pass

    if not cands:
        return GeneralGraph(nodes)
    if len(cands) == 1:
        return cands[0]

    # ---- Phase 2: Score-based model selection ----
    dags = [graph_to_dag(G) for G in cands]
    scores = [score_dag(d) for d in dags]
    bi = int(np.argmax(scores))

    # ---- Phase 3: DAG-space hill climbing refinement ----
    refined_dag = hc_refine(dags[bi].copy(), max_iters=50)
    refined_score = score_dag(refined_dag)

    if refined_score > scores[bi] + 1e-6:
        return to_cpdag(refined_dag)
    else:
        return cands[bi]
# =====================================================================

from causallearn.graph.GraphNode import GraphNode


def run_causal_discovery(X: np.ndarray) -> GeneralGraph:
    """
    Cross-Space Refinement (CSR): Initialize DAG from GES CPDAG,
    then refine via DAG-space hill-climbing with BDeu scores.
    Input:  X of shape (n_samples, n_variables), integer-encoded discrete data
    Output: estimated CPDAG as causallearn.graph.GeneralGraph.GeneralGraph
    """
    from causallearn.search.ScoreBased.GES import ges
    from causallearn.score.LocalScoreFunctionClass import LocalScoreClass
    from causallearn.score.LocalScoreFunction import local_score_BDeu
    from causallearn.utils.DAG2CPDAG import dag2cpdag
    from causallearn.graph.Endpoint import Endpoint

    n, N = X.shape
    nodes = [GraphNode(f"X{i+1}") for i in range(N)]
    score_func = LocalScoreClass(
        data=X, local_score_fun=local_score_BDeu, parameters=None
    )

    # Phase 1: GES — search in CPDAG (equivalence-class) space
    result = ges(
        X, score_func="local_score_BDeu",
        parameters={"sample_prior": 1.0, "structure_prior": 1.0},
    )
    G_cpdag = result["G"]

    # Phase 2: Extract a consistent DAG extension from the CPDAG
    adj = np.zeros((N, N), dtype=int)
    undirected = []
    for i in range(N):
        for j in range(i + 1, N):
            edge = G_cpdag.get_edge(G_cpdag.nodes[i], G_cpdag.nodes[j])
            if edge is None:
                continue
            n1 = edge.get_node1()
            ep1, ep2 = edge.get_endpoint1(), edge.get_endpoint2()
            if n1 == G_cpdag.nodes[i]:
                ep_i, ep_j = ep1, ep2
            else:
                ep_i, ep_j = ep2, ep1
            if ep_i == Endpoint.TAIL and ep_j == Endpoint.ARROW:
                adj[i, j] = 1  # directed i -> j
            elif ep_i == Endpoint.ARROW and ep_j == Endpoint.TAIL:
                adj[j, i] = 1  # directed j -> i
            else:
                undirected.append((i, j))

    def _has_path(src, tgt):
        """DFS: is there a directed path src -> ... -> tgt?"""
        visited = set()
        stack = [src]
        while stack:
            nd = stack.pop()
            if nd == tgt:
                return True
            if nd in visited:
                continue
            visited.add(nd)
            for c in np.where(adj[nd] == 1)[0]:
                if int(c) not in visited:
                    stack.append(int(c))
        return False

    # Resolve undirected edges using BDeu score comparison + acyclicity
    for (i, j) in undirected:
        can_ij = not _has_path(j, i)
        can_ji = not _has_path(i, j)
        if can_ij and can_ji:
            nj = sorted(np.where(adj[:, j] == 1)[0].tolist())
            ni = sorted(np.where(adj[:, i] == 1)[0].tolist())
            d_ij = score_func.score(j, sorted(nj + [i])) - score_func.score(j, nj)
            d_ji = score_func.score(i, sorted(ni + [j])) - score_func.score(i, ni)
            if d_ij <= d_ji:
                adj[i, j] = 1
            else:
                adj[j, i] = 1
        elif can_ij:
            adj[i, j] = 1
        else:
            adj[j, i] = 1

    # Phase 3: DAG-space hill-climbing refinement (add/delete/reverse)
    local_scores = np.zeros(N)
    for j in range(N):
        local_scores[j] = score_func.score(
            j, sorted(np.where(adj[:, j] == 1)[0].tolist())
        )

    improved = True
    while improved:
        improved = False
        best_delta = 0.0
        best_op = None
        for i in range(N):
            for j in range(N):
                if i == j:
                    continue
                if adj[i, j] == 0 and adj[j, i] == 0:
                    # Try ADD i -> j
                    if not _has_path(j, i):
                        pj_new = sorted(
                            np.where(adj[:, j] == 1)[0].tolist() + [i]
                        )
                        delta = score_func.score(j, pj_new) - local_scores[j]
                        if delta < best_delta - 1e-6:
                            best_delta = delta
                            best_op = ("add", i, j)
                elif adj[i, j] == 1:
                    # Try DELETE i -> j
                    pj_new = sorted(
                        [p for p in np.where(adj[:, j] == 1)[0] if p != i]
                    )
                    delta = score_func.score(j, pj_new) - local_scores[j]
                    if delta < best_delta - 1e-6:
                        best_delta = delta
                        best_op = ("delete", i, j)
                    # Try REVERSE i -> j  to  j -> i
                    adj[i, j] = 0
                    if not _has_path(i, j):
                        pj_del = sorted(
                            np.where(adj[:, j] == 1)[0].tolist()
                        )
                        pi_new = sorted(
                            np.where(adj[:, i] == 1)[0].tolist() + [j]
                        )
                        delta = (
                            score_func.score(j, pj_del) - local_scores[j]
                        ) + (
                            score_func.score(i, pi_new) - local_scores[i]
                        )
                        if delta < best_delta - 1e-6:
                            best_delta = delta
                            best_op = ("reverse", i, j)
                    adj[i, j] = 1
        if best_op is not None:
            op, i, j = best_op
            if op == "add":
                adj[i, j] = 1
            elif op == "delete":
                adj[i, j] = 0
            elif op == "reverse":
                adj[i, j] = 0
                adj[j, i] = 1
            local_scores[j] = score_func.score(
                j, sorted(np.where(adj[:, j] == 1)[0].tolist())
            )
            if op == "reverse":
                local_scores[i] = score_func.score(
                    i, sorted(np.where(adj[:, i] == 1)[0].tolist())
                )
            improved = True

    # Build output CPDAG
    G = GeneralGraph(nodes)
    for i in range(N):
        for j in range(N):
            if adj[i, j] == 1:
                G.add_directed_edge(nodes[i], nodes[j])
    return dag2cpdag(G)

from causallearn.graph.GraphNode import GraphNode


def run_causal_discovery(X: np.ndarray) -> GeneralGraph:
    """
    Constraint-Informed Score-Based Discovery (CISB).
    Hybrid: PC skeleton -> greedy BDeu orientation -> HC refinement -> CPDAG.
    """
    from causallearn.utils.PCUtils import SkeletonDiscovery
    from causallearn.utils.cit import CIT
    from causallearn.score.LocalScoreFunctionClass import LocalScoreClass
    from causallearn.score.LocalScoreFunction import local_score_BDeu
    from causallearn.utils.DAG2CPDAG import dag2cpdag

    n_samples, d = X.shape
    nodes = [GraphNode(f"X{i + 1}") for i in range(d)]

    # Phase 1: PC-stable skeleton discovery with chi-squared test
    indep_test = CIT(X, "chisq")
    cg = SkeletonDiscovery.skeleton_discovery(
        X, 0.05, indep_test, stable=True,
        background_knowledge=None, verbose=False,
        show_progress=False, node_names=None,
    )
    skel = np.zeros((d, d), dtype=int)
    for i in range(d):
        for j in range(i + 1, d):
            if cg.G.get_edge(nodes[i], nodes[j]) is not None:
                skel[i, j] = 1
                skel[j, i] = 1

    # Phase 2: BDeu score setup
    score_fn = LocalScoreClass(
        data=X, local_score_fun=local_score_BDeu, parameters=None
    )
    adj = np.zeros((d, d), dtype=int)
    local_scores = np.array([score_fn.score(j, []) for j in range(d)])

    def has_path(src, tgt):
        visited = set()
        stack = [src]
        while stack:
            u = stack.pop()
            if u == tgt:
                return True
            if u in visited:
                continue
            visited.add(u)
            for c in np.where(adj[u] == 1)[0]:
                c = int(c)
                if c not in visited:
                    stack.append(c)
        return False

    # Phase 3: Greedy orientation of skeleton edges by BDeu score
    for i in range(d):
        for j in range(i + 1, d):
            if skel[i, j] == 0:
                continue
            pj = sorted(np.where(adj[:, j] == 1)[0].tolist())
            s_ij = score_fn.score(j, sorted(pj + [i]))
            d_ij = s_ij - local_scores[j]
            pi = sorted(np.where(adj[:, i] == 1)[0].tolist())
            s_ji = score_fn.score(i, sorted(pi + [j]))
            d_ji = s_ji - local_scores[i]
            if d_ij <= d_ji:
                if not has_path(j, i):
                    adj[i, j] = 1
                    local_scores[j] = s_ij
                elif not has_path(i, j):
                    adj[j, i] = 1
                    local_scores[i] = s_ji
            else:
                if not has_path(i, j):
                    adj[j, i] = 1
                    local_scores[i] = s_ji
                elif not has_path(j, i):
                    adj[i, j] = 1
                    local_scores[j] = s_ij

    # Phase 4: Hill-climbing refinement (add / delete / reverse)
    improved = True
    while improved:
        improved = False
        best_delta = 0.0
        best_op = None
        for i in range(d):
            for j in range(d):
                if i == j:
                    continue
                if adj[i, j] == 0 and adj[j, i] == 0:
                    if not has_path(j, i):
                        pj_n = sorted(
                            np.where(adj[:, j] == 1)[0].tolist() + [i]
                        )
                        delta = score_fn.score(j, pj_n) - local_scores[j]
                        if delta < best_delta - 1e-6:
                            best_delta = delta
                            best_op = ("add", i, j)
                elif adj[i, j] == 1:
                    pj_n = sorted(
                        [p for p in np.where(adj[:, j] == 1)[0] if p != i]
                    )
                    delta = score_fn.score(j, pj_n) - local_scores[j]
                    if delta < best_delta - 1e-6:
                        best_delta = delta
                        best_op = ("delete", i, j)
                    adj[i, j] = 0
                    if not has_path(i, j):
                        sj = score_fn.score(
                            j, sorted(np.where(adj[:, j] == 1)[0].tolist())
                        )
                        si = score_fn.score(
                            i,
                            sorted(np.where(adj[:, i] == 1)[0].tolist() + [j]),
                        )
                        delta = (sj - local_scores[j]) + (si - local_scores[i])
                        if delta < best_delta - 1e-6:
                            best_delta = delta
                            best_op = ("reverse", i, j)
                    adj[i, j] = 1
        if best_op is not None:
            op, i, j = best_op
            if op == "add":
                adj[i, j] = 1
            elif op == "delete":
                adj[i, j] = 0
            elif op == "reverse":
                adj[i, j] = 0
                adj[j, i] = 1
            local_scores[j] = score_fn.score(
                j, sorted(np.where(adj[:, j] == 1)[0].tolist())
            )
            if op == "reverse":
                local_scores[i] = score_fn.score(
                    i, sorted(np.where(adj[:, i] == 1)[0].tolist())
                )
            improved = True

    # Build output graph and convert to CPDAG
    G = GeneralGraph(nodes)
    for i in range(d):
        for j in range(d):
            if adj[i, j] == 1:
                G.add_directed_edge(nodes[i], nodes[j])
    return dag2cpdag(G)
